interface.signature:
interface WorkerMetricsDTO {
  cpu_history: Array<{ timestamp: string; cpu_percent: number }>;
  memory_history: Array<{ timestamp: string; memory_percent: number }>;
  throughput_history: Array<{ timestamp: string; tasks_per_minute: number }>;
  worker_config: WorkerConfigDTO;
}

interface WorkerConfigDTO {
  os_name: string;
  python_version: string;
  celery_version: string;
  queues: string[];
  max_tasks_per_child: number | null;
  concurrency: number;
  pool_type: string;
}

function useWorkerMetrics(hostname: string) {
  return useQuery({
    queryKey: ['worker-metrics', hostname],
    queryFn: () => getWorkerMetrics(hostname),
    staleTime: 5 * 60 * 1000, // 5 minutes
    enabled: !!hostname,
  });
}
